import{z as B,x as i,o as A,c as p,q as r,j as t,D as n,d as e,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"均匀与非均匀量化","description":"","frontmatter":{"title":"均匀与非均匀量化","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/uniform-nonuniform-quant.md","filePath":"llm/uniform-nonuniform-quant.md","lastUpdated":1791063341000}'),m={name:"llm/uniform-nonuniform-quant.md"};function d(u,a,D,T,f,h){const l=i("Mermaid");return A(),p("div",null,[a[2]||(a[2]=r('<h1 id="均匀与非均匀量化" tabindex="-1">均匀与非均匀量化 <a class="header-anchor" href="#均匀与非均匀量化" aria-label="Permalink to &quot;均匀与非均匀量化&quot;">​</a></h1><div class="epigraph"><p>均匀格子把动态范围等分成 $2^b$ 份；非均匀格子把码字堆到概率质量高的地方。两者都叫量化，误差曲线对离群与对正态权重完全不同。</p><footer>—— 对照经典标量量化与 LLM 里 INT 网格 / 分位码本；部署实例见 GPTQ</footer></div><p><a href="/llm/quantization-vs-prune">上一课</a>把「压缩与数值」课序收在量化误差与剪枝的分工：剪完必须重校准量化统计，功能离群维留精度，验收看联合图。本课打开「量化基础与稀疏」，先讲格子本身。缺口不是从信息论第一课重讲率失真，而是 <strong>均匀与非均匀在 LLM 权重/激活上各自伤害哪一段分布</strong>。后课对称性、粒度、校准都假定你会：量化是一个编码器 \\(q\\) 加一个反编码器，误差在连续值与有限码本之间。<a href="/llm/gptq">GPTQ</a> 默认均匀分组格子；<a href="/llm/qlora">QLoRA</a> 的 NF4 是非均匀分位——后课再展开，本课只把对立建清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记实数 \\(x\\)，码本 \\(\\mathcal{C}=\\{c_0,\\ldots,c_{2^b-1}\\}\\)，\\(q(x)=\\arg\\min_c |x-c|\\)（或带随机舍入）。均匀：\\(\\mathcal{C}\\) 是等差，由尺度 \\(s\\) 与可选零点决定。非均匀：间距随 \\(x\\) 变，或由分位数 / k-means / 手工码本给出。LLM 权重大致零峰、近似正态；激活常有<a href="/llm/why-activation-outliers">离群通道</a>。均匀格子为覆盖离群把 \\(s\\) 拉大，中间的质量挤成几个台阶；非均匀把台阶堆在零附近，离群要么单独码字、要么饱和。</p><p><span class="marginnote">码本就是一张对照表：量化时把任意实数映射到表里最近的一个代表值，反量化时再查回。表的条目数固定是 \\(2^b\\) 个——\\(b=8\\) 有 256 个台阶，\\(b=4\\) 只有 16 个；台阶越少，每个代表值就越「将就」，误差也越大。</span></p><p>硬件喜欢均匀：INT8 GEMM 是整数乘加再乘 \\(s\\)。非均匀要查表或分段，核少、吞吐差，除非码本极小且实现成对表。问题是 <strong>统计上更优的码本，部署上可能没有核</strong>——对比方法课的软件/硬件维在此落地。</p><p><span class="marginnote">本站「量化」在金融栏是微观结构，与权重量化无关。本课程只指数值离散化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>均匀：选 \\(s\\)（常按 max 或百分位）、可选 clip，然后 round。实现与 Tensor Core INT 路径对齐。<a href="/llm/gptq">GPTQ</a> / AWQ 主线都在这张网上改「取哪一个台阶」或「如何保护通道」，并不换码本几何。</p><p>非均匀：分位码本（后课 NF4）、对数量化、k-means 聚类码本（早期 Deep Compression）。训练期可学码本，推理就要把码本存下来并有核。PTQ 里对一层做 k-means 往往过拟合校准集，且 175B 上算不起——这是 GPTQ 坚持均匀的工程原因之一。</p>',11)),(A(),t(s,null,{default:n(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BF%9E%E7%BB%AD%E6%9D%83%E9%87%8D%20%2F%20%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20U%5B%22%E5%9D%87%E5%8C%80%E6%A0%BC%E5%AD%90%20%2B%20%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20X%20--%3E%20NU%5B%22%E5%88%86%E4%BD%8D%20%2F%20%E8%81%9A%E7%B1%BB%E7%A0%81%E6%9C%AC%22%5D%0A%20%20U%20--%3E%20HW%5B%22INT%20GEMM%20%E6%A0%B8%22%5D%0A%20%20NU%20--%3E%20LUT%5B%22%E6%9F%A5%E8%A1%A8%E6%88%96%E7%89%B9%E5%8C%96%E6%A0%B8%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"混合：多数值均匀，离群通道留高精（LLM.int8() 一类）——这是非均匀的极端：码本在通道维上不共享。它不是新的 \\(b\\) bit，是粒度与混合精度，后课再写。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"均匀误差在 \\([-s/2,s/2]\\) 量级（未饱和时）。\\(s\\) 由极值决定时，误差被离群绑架。非均匀若按输入分布的分位切，量化噪声在高密度区更小，等效提高「中间权重」的信噪比；尾部误差更大或靠饱和。权重近似高斯时，分位码本接近对正态最优的标量量化；激活离群时，任何全局码本都不够，必须先拆通道。",-1)),a[6]||(a[6]=E("p",null,"随机舍入让均匀量化无偏，利于训练（QAT）与某些梯度通信；推理 PTQ 多用确定 round-to-nearest，好复现。不要混。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"数字实例：\\(b=4\\)、权重范围 \\([-2,2]\\) 时，均匀格子每格宽 \\(4/16=0.25\\)。若出现一个 \\(8\\) 的离群值，尺度必须撑到覆盖 \\([-8,8]\\)，每格宽被拉到约 \\(1\\)——普通权重四舍五入一次的偏差可能放大四倍。这就是「离群绑架 \\(s\\)」的具体含义。")],-1)),(A(),t(s,null,{default:n(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%99%AE%E9%80%9A%E6%9D%83%E9%87%8D%E6%8C%A4%E5%9C%A8%E9%9B%B6%E9%99%84%E8%BF%91%22%5D%20--%3E%20S%5B%22%E4%B8%80%E4%B8%AA%E7%A6%BB%E7%BE%A4%E5%80%BC%E6%8A%8A%E5%B0%BA%E5%BA%A6%20s%20%E6%92%91%E5%A4%A7%22%5D%0A%20%20S%20--%3E%20STEP%5B%22%E5%8F%B0%E9%98%B6%E5%AE%BD%E5%BA%A6%E9%9A%8F%E4%B9%8B%E5%8F%98%E5%AE%BD%22%5D%0A%20%20STEP%20--%3E%20MID%5B%22%E5%AF%86%E9%9B%86%E5%8C%BA%E8%A2%AB%E5%8E%8B%E8%BF%9B%E5%B0%91%E6%95%B0%E5%87%A0%E4%B8%AA%E5%8F%B0%E9%98%B6%22%5D%0A%20%20MID%20--%3E%20ERR%5B%22%E5%A4%A7%E5%A4%9A%E6%95%B0%E6%9D%83%E9%87%8D%E7%9A%84%E8%88%8D%E5%85%A5%E8%AF%AF%E5%B7%AE%E4%B8%8A%E5%8D%87%22%5D%0A%20%20S%20--%3E%20SAT%5B%22%E6%88%96%E7%9B%B4%E6%8E%A5%E6%88%AA%E6%96%AD%E7%A6%BB%E7%BE%A4%E5%80%BC%22%5D%0A%20%20SAT%20--%3E%20LOSE%5B%22%E7%A6%BB%E7%BE%A4%E9%80%9A%E9%81%93%E4%BF%A1%E6%81%AF%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20ERR%20--%3E%20OUT%5B%22%E5%AF%B9%E7%AD%96%EF%BC%9A%E7%99%BE%E5%88%86%E4%BD%8D%E6%88%AA%E6%96%AD%20%2F%20%E6%8C%89%E9%80%9A%E9%81%93%E5%8D%95%E7%8B%AC%E5%AE%9A%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20LOSE%20--%3E%20OUT%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p><span class="marginnote">对数格子对动态范围极大的激活有旧文献；现代 LLM 更常做迁移平滑或混精，而不是真的对数 ALU。没有核的对数量化只是分析工具。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「非均匀一定更准」写成部署结论。不要在没有反量化约定时交换均匀 INT4 检查点与 NF4 检查点。不要用权重直方图的最优码本去量化激活。下一课在均匀格子内部再切一刀：对称还是带零点。</p><p><span class="marginnote">常见误区：初学者容易以为「非均匀」只是把格子间距改成不等长、其余照旧。实际上它改变的是整条计算路径——均匀格反量化只要一次乘法，非均匀格要查表或上特化核；统计上省下的那点误差，可能在部署时被吞吐损失吞回去。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>均匀：等差码本 + 尺度，对齐 INT 核；离群绑架 \\(s\\)。</li><li>非均匀：码字跟分布走，常需查表；NF4 是后课的分位实例。</li><li>GPTQ 类 PTQ 主线是均匀网格上的误差补偿，不是换码本。</li><li>统计最优与硬件核可能冲突；验收用最终核路径。</li><li>出处：标量量化常识；GPTQ 均匀网格；QLoRA NF4 作对照入口。</li></ul>',6))])}const C=B(m,[["render",d]]);export{b as __pageData,C as default};
